WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( /* Old List (107 Cities) */ -- VALUES -- (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), -- (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), -- (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), -- (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), -- (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), -- (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), -- (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), -- (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), -- (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), -- (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), -- (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), -- (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), -- (205655),(94782),(300439) /* New List (120 Cities) */ VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815),(247), (307614),(289873),(76480),(204358),(298723),(82558),(75103),(517),(265316),(231), (1529),(879),(217335),(1242),(71642),(93968),(74124),(142),(636),(1136),(520),(669), (1061),(77167),(275),(69526),(802),(196),(1528),(77530),(200347),(305974),(68747), (735),(84848),(197504),(216551),(68705),(1343),(80438),(427),(77687),(73533),(196096), (202212),(711),(78796),(489),(747),(93580),(466),(77705),(68871),(1148),(1459),(361), (471),(70983),(81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475),(74130),(215191), (84310),(1496),(403),(1141),(189),(133),(177),(1351),(70628),(74708),(66007),(198750), (663),(94877),(71756),(1128),(293),(534),(77093),(154),(1001),(70030),(576),(70429), (217),(960),(196420),(94782),(300439) ) AS x(dest_id) ), ui AS ( SELECT event_value, mri_session_id, mri_client_id FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-02-01 00:00:00' -- only Nov AND event_name = 'Tuple clicked' AND event_value IN ('RTR available', 'RTR not available') AND event_src = 'Android' AND header_country = 'IND' ), -- all base confirmations in Nov (all txns) co AS ( SELECT rb_user_id, "source_location_id" AS base_src_id, "destination_location_id" AS base_dest_id, tin, CASE WHEN destination_location_id IN (SELECT dest_id FROM piligrim_dest_list) THEN 'Pilgrim' ELSE 'non-Pilgrim' END AS Pilgrim, time_of_event AS txted_date, mri_session_id, mri_client_id FROM transaction.bus_ticket_events WHERE "time_of_event" >= TIMESTAMP '2026-01-01 00:00:00' AND "time_of_event" < TIMESTAMP '2026-02-01 00:00:00' -- base month = Nov AND sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') AND country_code = 'IND' AND event_class = 2 AND event_type = 101 AND tin IS NOT NULL AND rb_user_id > 0 AND business_unit = 'REDBUS_IN' ), -- return search within 15 days after each base txn, on reverse SD all_post_search AS ( SELECT b.rb_user_id, b.base_src_id, b.base_dest_id, b.txted_date, s.src_id AS search_src_id, -- return src (base_dest) s.dest_id AS search_dest_id, -- return dest (base_src) s.__time AS searchdate FROM co b JOIN user_interaction.search_details s ON s.rb_user_id = b.rb_user_id AND s.__time > b.txted_date AND s.__time < date_add('day', 15, b.txted_date) -- search within 15 days of base AND s.os = 'Android' AND s.country = 'IND' -- reverse SD: return journey AND b.base_src_id = s.dest_id AND b.base_dest_id = s.src_id ), -- first return confirmation per user–return SD that: -- * happens after search -- * and is also within 15 days of the base txn return_tickets AS ( SELECT a.rb_user_id, a.search_src_id, a.search_dest_id, MIN(r.time_of_event) AS first_ret_txted_date FROM all_post_search a INNER JOIN transaction.bus_ticket_events r ON r.rb_user_id = a.rb_user_id AND r.source_location_id = a.search_src_id -- same return SD AND r.destination_location_id = a.search_dest_id AND r.time_of_event > a.searchdate -- after the search AND r.time_of_event < date_add('day', 15, a.txted_date) -- also within 15 days of base AND sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') AND country_code = 'IND' AND event_class = 2 AND event_type = 101 AND tin IS NOT NULL AND business_unit = 'REDBUS_IN' GROUP BY a.rb_user_id, a.search_src_id, a.search_dest_id ) SELECT co.Pilgrim, COALESCE(ui.event_value, 'Unknown') AS rtr_type, COUNT(DISTINCT co.rb_user_id) AS "Txted Users", COUNT(DISTINCT aps.rb_user_id) AS "Searched for return", COUNT(DISTINCT rt.rb_user_id) AS "Txted for Return" FROM co LEFT JOIN ui ON ui.mri_session_id = co.mri_session_id AND ui.mri_client_id = co.mri_client_id LEFT JOIN all_post_search aps ON aps.rb_user_id = co.rb_user_id AND aps.search_src_id = co.base_src_id AND aps.search_dest_id = co.base_dest_id LEFT JOIN return_tickets rt ON rt.rb_user_id = aps.rb_user_id AND rt.search_src_id = aps.search_src_id AND rt.search_dest_id = aps.search_dest_id GROUP BY COALESCE(ui.event_value, 'Unknown'), co.Pilgrim ;
